async function main() {
  console.log("Creating Daytona client...");
  const daytona = new Daytona();

  console.log("Creating sandbox...");
  const sandbox = await daytona.create();
  console.log(`Sandbox created with ID: ${sandbox.id}`);

  console.log("Waiting for sandbox to start...");
  await sandbox.waitForSandboxStart();
  console.log(`Sandbox state: ${sandbox.state}`);

  console.log("Running code inside the sandbox...");
  const response = await sandbox.process.codeRun(`
function greet(name) {
  return \`Hello, \${name}!\`;
}
console.log(greet("Daytona"));
`);
  console.log(`Code execution result: ${response.result}`);

  console.log("Removing sandbox...");
  await sandbox.delete();
  console.log("Done!");
}

